def refs():
    return [{**s, "subject": "science", "locator": "酵素催化、專一性、溫度與酸鹼度、反應速率及控制變因", "observedPattern": "公開公立學校自然科資料常用澱粉分解、消化酵素、溫度／pH 曲線及對照組判讀；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-bc-iv-1-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然科資料僅供酵素催化、專一性、條件影響與實驗設計的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開公立學校自然科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "酵素能讓細胞內許多反應在適合的溫度下快速進行，最符合的解釋是？", {"A": "降低反應所需的活化能", "B": "把反應物的質量變成零", "C": "讓所有反應都必定放熱", "D": "把細胞溫度提高到沸點"}, "A", "酵素提供較容易進行的反應途徑，降低活化能，使反應速率增加；它不是把質量消除，選 A。", "先分清酵素影響的是反應速率，不是守恆量或反應熱。", ["確認題目問的是反應進行快慢。", "酵素提供替代反應途徑。", "替代途徑的活化能較低。", "較多粒子能在相同條件下達到反應門檻。", "所以酵素作用是降低活化能，選 A。"], "easy"),
    make(2, "某酵素只能催化澱粉分解，不能催化脂肪分解。這項現象最能支持哪個概念？", {"A": "酵素具有專一性", "B": "所有酵素都能作用於所有受質", "C": "酵素會把脂肪變成澱粉", "D": "酵素只能在沸水中作用"}, "A", "酵素活性部位的形狀與化學性質只適合部分受質，因此不同酵素有不同作用對象，選 A。", "把『能催化哪種受質』和『作用條件』分成兩個概念判斷。", ["列出題目中的酵素與兩種受質。", "比較實際觀察到的催化對象。", "作用對象有選擇性，不是所有受質都能結合。", "這種選擇性來自活性部位的互補性。", "因此是酵素專一性，選 A。"], "easy"),
    make(3, "以唾液澱粉酶研究溫度影響時，37°C 組比 5°C 組產生較多還原糖。下列結論何者最恰當？", {"A": "在這組條件與觀察時間內，37°C 的反應速率較快", "B": "37°C 組的酵素質量一定較多", "C": "只要溫度更高，反應速率永遠更快", "D": "還原糖越多就代表酵素被消耗越多"}, "A", "相同材料與時間的比較中，產物形成量較多表示該段時間的平均反應速率較快；但不能推論高溫永遠更好，選 A。", "只從受控實驗的資料範圍下結論，避免把局部結果外推成永遠成立。", ["確認兩組只把溫度當主要自變因。", "比較相同時間內還原糖的生成量。", "37°C 組生成較多，代表平均速率較快。", "資料沒有證明更高溫度一定持續增加速率。", "所以在本實驗範圍內選 A。"], "medium"),
    make(4, "研究胃蛋白酶的酸鹼度時，哪一組最適合作為『沒有酵素』的對照？", {"A": "加入等量受質與緩衝液，但以等量清水取代酵素", "B": "同時改變酵素量、受質量與 pH", "C": "只放受質，不記錄反應時間", "D": "把有酵素組加熱到沸騰，對照組不加熱"}, "A", "以清水取代酵素而維持其他條件，可比較沒有酵素時的背景變化，符合對照組設計，選 A。", "先確定要排除的變因，再讓對照組只缺少該因素。", ["研究問題是酵素是否造成反應差異。", "受質、體積、pH 與時間要盡量相同。", "對照組只把酵素換成等量清水。", "兩組結果差異才可歸因於酵素存在。", "所以選 A。"], "medium"),
    make(5, "某酵素在 40°C 活性最高；加熱到 90°C 後幾乎沒有活性，冷卻回 40°C 也未恢復。最可能的原因是？", {"A": "高溫使酵素蛋白質構形改變而變性", "B": "高溫讓所有受質自動消失", "C": "冷卻會把酵素轉成脂肪", "D": "酵素只要離開細胞就必定蒸發"}, "A", "90°C 可能破壞酵素維持構形的作用力，使活性部位形狀改變；降溫不一定能恢復，稱為變性，選 A。", "利用『高溫後不可逆』的線索，區分暫時速率下降與結構變性。", ["先找出最佳溫度與高溫處理結果。", "高溫後冷卻仍無活性，表示不只是粒子運動變慢。", "酵素的蛋白質構形可能被破壞。", "活性部位改變後，受質不易正確結合。", "因此最合理是變性，選 A。"], "hard"),
    make(6, "下列哪項最適合用來表示酵素反應『速率』，而不是只表示最後累積的產物量？", {"A": "單位時間內產物增加量", "B": "反應結束時的總產物量，不記錄時間", "C": "試管的顏色名稱", "D": "加入試管的標籤數量"}, "A", "速率是單位時間的變化量，例如單位時間生成多少產物；只看終點量無法排除反應時間不同，選 A。", "看到速率就找『變化量除以時間』，並檢查是否有可比較的時間尺度。", ["指出要追蹤的量是產物。", "記錄反應前後或連續時間的產物變化。", "用產物增加量除以經過時間。", "相同時間區段的值才能比較反應快慢。", "所以選 A。"], "medium"),
    make(7, "若要比較不同 pH 對同一酵素活性的影響，哪個設計最能支持公平比較？", {"A": "固定酵素量、受質量、溫度與時間，只改變 pH", "B": "每個 pH 同時使用不同酵素與不同受質", "C": "一組測氣泡量，另一組測顏色深淺", "D": "先讓各組反應不同時間再比較產物"}, "A", "要把 pH 的影響單獨分離，其他會影響速率的條件須保持一致；A 才符合控制變因，選 A。", "把自變因、應變因與控制變因逐一列出，確認只有一項被改變。", ["自變因設定為 pH。", "酵素量與受質量固定，避免材料差異干擾。", "溫度與反應時間也固定。", "用同一種產物指標比較活性。", "所以選 A。"], "medium"),
    make(8, "鳳梨汁能使明膠較難凝固。若要判斷是否為鳳梨中的蛋白酶造成，哪個結果最有說服力？", {"A": "加熱處理使鳳梨汁失去作用，未加熱鳳梨汁仍能分解蛋白質", "B": "所有果汁都讓明膠完全不凝固", "C": "只觀察鳳梨顏色而不做對照", "D": "加入越多水就說明酵素活性越高"}, "A", "加熱可能使蛋白酶變性；若只有未加熱鳳梨汁保有分解效果，且有適當對照，能支持酵素參與的解釋，選 A。", "找同一材料的處理組與對照組，再以酵素可能受高溫影響的可預測結果判讀。", ["設定未加熱與加熱鳳梨汁兩組。", "保持明膠量、溫度與時間相同。", "比較兩組凝固或蛋白質分解結果。", "加熱失活而未加熱有效，符合酵素變性的預測。", "所以選 A。"], "hard"),
    make(9, "某實驗在相同 pH 下增加澱粉濃度，初期反應速率變快，之後趨於固定。哪個解釋最合理？", {"A": "受質增加可增加碰撞機會，但酵素活性部位有限", "B": "澱粉濃度越高會讓酵素數量自動增加", "C": "反應速率固定表示沒有酵素參與", "D": "所有受質都能同時占滿無限多個活性部位"}, "A", "低濃度時增加受質提高碰撞機會；當多數活性部位已被占用，速率會接近上限，選 A。", "讀曲線先看斜率，再用酵素活性部位數量解釋平台。", ["先確認 pH、溫度與酵素量固定。", "初期受質增加使酵素與受質碰撞更頻繁。", "繼續增加受質後，活性部位逐漸飽和。", "活性部位有限使速率不再同比增加。", "因此選 A。"], "hard"),
    make(10, "有一組試管的酵素反應產物較少。僅憑這項結果，哪個結論不能直接推出？", {"A": "酵素一定已經完全失效", "B": "該組在測量時間內的產物生成量較少", "C": "可能存在溫度或 pH 不適等抑制因素", "D": "需要檢查控制變因與測量方法"}, "A", "產物較少只能說明觀察期間的結果較低，可能由條件、時間或測量誤差造成，不能直接斷定酵素完全失效，選 A。", "區分資料直接支持的描述、合理假說與超出證據的斷言。", ["先寫出資料真正測到的是產物量。", "產物少可反映速率較慢，但原因不唯一。", "溫度、pH、材料量與測量誤差都需檢查。", "沒有額外證據就不能宣稱酵素完全失效。", "所以不能直接推出 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    old = {option["id"]: option["text"] for option in q["options"]}
    old_a, old_target = old["A"], old[target]
    old["A"], old[target] = old_target, old_a
    q["options"] = [{"id": key, "text": old[key]} for key in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A", f"選 {target}")
    q["solutionStrategy"] = q["solutionStrategy"].replace("選 A", f"選 {target}")
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("因此 A", f"因此 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
